WITH source AS MATERIALIZED(SELECT DISTINCT PID FROM Person WHERE TRIM(Name)='Shah Rukh Khan' OR TRIM(Name)='Shahrukh Khan'),cast_clean AS MATERIALIZED(SELECT DISTINCT MID,TRIM(PID) pid FROM M_Cast),source_films AS MATERIALIZED(SELECT DISTINCT c.MID FROM cast_clean c JOIN source s ON c.pid=s.PID),first_hop AS MATERIALIZED(SELECT DISTINCT c.pid FROM cast_clean c JOIN source_films f USING(MID)),next_films AS MATERIALIZED(SELECT DISTINCT c.MID FROM cast_clean c JOIN first_hop h USING(pid)),second_hop AS MATERIALIZED(SELECT DISTINCT c.pid FROM cast_clean c JOIN next_films f USING(MID) EXCEPT SELECT pid FROM first_hop EXCEPT SELECT PID FROM source) SELECT (SELECT COUNT(*) FROM second_hop) d2,(SELECT COUNT(*) FROM first_hop WHERE pid NOT IN(SELECT PID FROM source)) d1,(SELECT COUNT(DISTINCT c.pid) FROM cast_clean c JOIN next_films f USING(MID)) reachable_within_two,(SELECT COUNT(*) FROM second_hop WHERE pid IN (SELECT pid FROM first_hop)) overlaps
